-- V49 - Catalogo integral (auditoria visual 2026-11): NOMBRES E INSTRUCCIONES que no describian el movimiento del GIF.
-- SOLO cambia name_es, instructions_es e instruction_steps_es. No cambia banderas, patron, grupo, musculos,
-- dificultad, equipamiento, prescripcion ni actividad. instructions_en conserva el texto de la fuente (trazabilidad).
-- Evidencia: GIF original (8 fotogramas + imagen) revisado por el revisor del lote; textos redactados describiendo solo
-- lo que el GIF muestra (protocolo en docs/FitSense/catalogo_integral/). Ningun nombre nuevo cambia el resultado de
-- las reglas por nombre (ImpactoPolicy, exclusion por «estiramiento») salvo el 1093, documentado: pierde «correr»
-- y su impacto por nombre pasa de MODERADO a BAJO, que es lo que muestra el GIF (sin fase de vuelo).
-- Cada fila exige el texto anterior exacto (name_es, o md5 de instructions_es con los saltos de linea normalizados): si no coincide, no cambia nada.

-- 55 ankle circles
UPDATE exercises SET instructions_es = 'Ponte de pie con las manos en la cadera. Apoya el peso en una pierna y eleva ligeramente el otro pie del suelo. Dibuja círculos lentos con el tobillo del pie elevado. Cambia el sentido del giro y después cambia de pie. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con las manos en la cadera.", "Apoya el peso en una pierna y eleva ligeramente el otro pie del suelo.", "Dibuja círculos lentos con el tobillo del pie elevado.", "Cambia el sentido del giro y después cambia de pie.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 55 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '3424f3c25a62f68d52edd0a39be605dd';
-- 58 45° side bend
UPDATE exercises SET instructions_es = 'Colócate de lado en un banco de hiperextensiones a 45°, con la cadera sobre el cojín y los pies sujetos bajo los rodillos. Coloca las manos detrás de la cabeza. Inclina el tronco lateralmente hacia el suelo con control. Eleva el tronco de lado hasta volver a alinearlo con las piernas. Completa las repeticiones y cambia de lado. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de lado en un banco de hiperextensiones a 45°, con la cadera sobre el cojín y los pies sujetos bajo los rodillos.", "Coloca las manos detrás de la cabeza.", "Inclina el tronco lateralmente hacia el suelo con control.", "Eleva el tronco de lado hasta volver a alinearlo con las piernas.", "Completa las repeticiones y cambia de lado.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 58 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'd4fab1de894022657ae6bfcea017ab88';
-- 61 arm slingers hanging bent knee legs
UPDATE exercises SET name_es = 'Elevación de rodillas colgado en correas abdominales', instructions_es = 'Engancha unas correas abdominales a una barra y apoya los brazos en ellas, con los codos dentro de las correas y las manos sujetándolas por encima de la cabeza. Deja el cuerpo colgado de las correas con los pies sin apoyo. Eleva las rodillas flexionadas hacia el pecho. Baja las piernas con control hasta estirarlas. Repite el número de repeticiones indicado.', instruction_steps_es = '["Engancha unas correas abdominales a una barra y apoya los brazos en ellas, con los codos dentro de las correas y las manos sujetándolas por encima de la cabeza.", "Deja el cuerpo colgado de las correas con los pies sin apoyo.", "Eleva las rodillas flexionadas hacia el pecho.", "Baja las piernas con control hasta estirarlas.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 61 AND name_es = 'Brazos sueltos colgantes con rodillas flexionadas' AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'af12a63b35a334652fb938efa003db04';
-- 62 arm slingers hanging straight legs
UPDATE exercises SET name_es = 'Elevación de piernas rectas colgado en correas abdominales', instructions_es = 'Engancha unas correas abdominales a una barra y apoya los brazos en ellas, con los codos dentro de las correas y las manos sujetándolas por encima de la cabeza. Deja el cuerpo colgado de las correas con los pies sin apoyo y las piernas estiradas. Eleva las piernas rectas al frente hasta la horizontal o algo más. Baja las piernas con control. Repite el número de repeticiones indicado.', instruction_steps_es = '["Engancha unas correas abdominales a una barra y apoya los brazos en ellas, con los codos dentro de las correas y las manos sujetándolas por encima de la cabeza.", "Deja el cuerpo colgado de las correas con los pies sin apoyo y las piernas estiradas.", "Eleva las piernas rectas al frente hasta la horizontal o algo más.", "Baja las piernas con control.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 62 AND name_es = 'Cables sujetando antebrazo con piernas rectas' AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '4166150e6be43422c258d767f6747fbd';
-- 66 back pec stretch
UPDATE exercises SET instructions_es = 'Ponte de pie frente a un banco inclinado, a algo más de la longitud de tus brazos. Flexiona la cadera y apoya las manos en el borde superior del respaldo con los brazos extendidos. Deja caer el pecho hacia el suelo hasta que los brazos queden en línea con el tronco, por encima de la cabeza, y notes el estiramiento en dorsales y pecho. Mantén las piernas casi rectas y la espalda larga. Mantén la duración indicada.', instruction_steps_es = '["Ponte de pie frente a un banco inclinado, a algo más de la longitud de tus brazos.", "Flexiona la cadera y apoya las manos en el borde superior del respaldo con los brazos extendidos.", "Deja caer el pecho hacia el suelo hasta que los brazos queden en línea con el tronco, por encima de la cabeza, y notes el estiramiento en dorsales y pecho.", "Mantén las piernas casi rectas y la espalda larga.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 66 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '515f18079618c8da25385f60593990db';
-- 68 arms apart circular toe touch (male)
UPDATE exercises SET instructions_es = 'Ponte de pie con los brazos extendidos por encima de la cabeza. Flexiona el tronco hacia delante y baja las manos hacia los pies. Sube describiendo un círculo con los brazos extendidos por delante del cuerpo. Termina con los brazos por encima de la cabeza y una ligera extensión de la espalda. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con los brazos extendidos por encima de la cabeza.", "Flexiona el tronco hacia delante y baja las manos hacia los pies.", "Sube describiendo un círculo con los brazos extendidos por delante del cuerpo.", "Termina con los brazos por encima de la cabeza y una ligera extensión de la espalda.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 68 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'abd6e914c069d76c84142da60f0444a6';
-- 94 balance board
UPDATE exercises SET instructions_es = 'Coloca la tabla de equilibrio en el suelo y sube a ella con ambos pies. Colócate erguido con los brazos relajados a los lados. Mantén la tabla estable haciendo pequeños ajustes con tobillos y cadera. Mantén la duración indicada.', instruction_steps_es = '["Coloca la tabla de equilibrio en el suelo y sube a ella con ambos pies.", "Colócate erguido con los brazos relajados a los lados.", "Mantén la tabla estable haciendo pequeños ajustes con tobillos y cadera.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 94 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'b687aec813c4134e57798f7d84b87cda';
-- 97 band single leg reverse calf raise
UPDATE exercises SET name_es = 'Elevación de puntas a una pierna con banda', instructions_es = 'Ponte de pie con un pie sobre un step y la otra pierna flexionada sin apoyar, con una mano apoyada en una pared. Pasa la banda por la parte delantera del pie de apoyo y sujeta el otro extremo con la otra mano. Eleva la punta del pie hacia la espinilla contra la resistencia de la banda. Baja la punta con control. Completa las repeticiones y cambia de pierna. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con un pie sobre un step y la otra pierna flexionada sin apoyar, con una mano apoyada en una pared.", "Pasa la banda por la parte delantera del pie de apoyo y sujeta el otro extremo con la otra mano.", "Eleva la punta del pie hacia la espinilla contra la resistencia de la banda.", "Baja la punta con control.", "Completa las repeticiones y cambia de pierna.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 97 AND name_es = 'Elevación de pantorrilla a una pierna invertida' AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '17c7c13c523feafbee9ca54286e38e99';
-- 103 band one arm twisting chest press
UPDATE exercises SET instructions_es = 'Siéntate en el suelo con las piernas extendidas y una banda anclada a un lado a la altura del pecho. Sujeta la banda con una mano junto al pecho, con el codo flexionado. Empuja la mano hacia delante hasta extender el brazo mientras giras el tronco. Vuelve con control a la posición inicial. Completa las repeticiones y cambia de brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en el suelo con las piernas extendidas y una banda anclada a un lado a la altura del pecho.", "Sujeta la banda con una mano junto al pecho, con el codo flexionado.", "Empuja la mano hacia delante hasta extender el brazo mientras giras el tronco.", "Vuelve con control a la posición inicial.", "Completa las repeticiones y cambia de brazo.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 103 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'f6353ebfd0f2843d1418aab2e2fc6d8f';
-- 104 band alternating v-up
UPDATE exercises SET instructions_es = 'Siéntate en el suelo con las piernas extendidas y el tronco reclinado. Sujeta con ambas manos una banda anclada frente a ti a la altura de los pies, con los brazos extendidos hacia ellos. Eleva una pierna recta hacia las manos. Baja la pierna con control y repite con la otra. Alterna los lados. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en el suelo con las piernas extendidas y el tronco reclinado.", "Sujeta con ambas manos una banda anclada frente a ti a la altura de los pies, con los brazos extendidos hacia ellos.", "Eleva una pierna recta hacia las manos.", "Baja la pierna con control y repite con la otra.", "Alterna los lados.", "Repite el número de repeticiones indicado."]'::jsonb
