-- 108 band jack knife sit-up
UPDATE exercises SET instructions_es = 'Túmbate boca arriba en el suelo con las piernas extendidas, los brazos a los lados y una banda anclada frente a los pies sujeta a los tobillos. Sube el tronco mientras llevas las rodillas flexionadas hacia el pecho. Mantén los brazos al frente durante la subida. Vuelve con control a la posición tumbada con las piernas extendidas. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate boca arriba en el suelo con las piernas extendidas, los brazos a los lados y una banda anclada frente a los pies sujeta a los tobillos.", "Sube el tronco mientras llevas las rodillas flexionadas hacia el pecho.", "Mantén los brazos al frente durante la subida.", "Vuelve con control a la posición tumbada con las piernas extendidas.", "Repite el número de repeticiones indicado."]'::jsonb
