-- 109 band kneeling twisting crunch
UPDATE exercises SET instructions_es = 'Arrodíllate en el suelo de espaldas a una banda anclada en alto. Sujeta la banda con ambas manos a los lados de la cabeza. Flexiona el tronco hacia abajo girándolo hacia un lado, llevando la cabeza hacia la rodilla. Vuelve a la posición erguida con control. Alterna los lados. Repite el número de repeticiones indicado.', instruction_steps_es = '["Arrodíllate en el suelo de espaldas a una banda anclada en alto.", "Sujeta la banda con ambas manos a los lados de la cabeza.", "Flexiona el tronco hacia abajo girándolo hacia un lado, llevando la cabeza hacia la rodilla.", "Vuelve a la posición erguida con control.", "Alterna los lados.", "Repite el número de repeticiones indicado."]'::jsonb
