UPDATE exercises SET name_es = 'Jalón sentado con banda anclada en alto', instructions_es = 'Siéntate en un cajón o banco frente a una banda anclada en alto. Sujeta las asas con los brazos extendidos hacia arriba. Tira de las asas hacia el pecho llevando los codos hacia abajo y atrás. Extiende los brazos con control. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en un cajón o banco frente a una banda anclada en alto.", "Sujeta las asas con los brazos extendidos hacia arriba.", "Tira de las asas hacia el pecho llevando los codos hacia abajo y atrás.", "Extiende los brazos con control.", "Repite el número de repeticiones indicado."]'::jsonb
