-- 119 band one arm twisting seated row
UPDATE exercises SET instructions_es = 'Siéntate en el suelo con las piernas extendidas y una banda anclada frente a ti. Sujeta la banda con una mano y el brazo extendido. Tira de la banda hacia el costado flexionando el codo mientras giras el tronco hacia ese lado. Extiende el brazo con control volviendo al centro. Completa las repeticiones y cambia de brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en el suelo con las piernas extendidas y una banda anclada frente a ti.", "Sujeta la banda con una mano y el brazo extendido.", "Tira de la banda hacia el costado flexionando el codo mientras giras el tronco hacia ese lado.", "Extiende el brazo con control volviendo al centro.", "Completa las repeticiones y cambia de brazo.", "Repite el número de repeticiones indicado."]'::jsonb
