-- 122 band hip lift
UPDATE exercises SET instructions_es = 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados. Coloca una banda sobre las caderas con los extremos fijados a cada lado, por ejemplo bajo discos que sujetas con las manos. Eleva la cadera contra la banda hasta alinear rodillas, cadera y hombros. Baja la cadera con control. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.", "Coloca una banda sobre las caderas con los extremos fijados a cada lado, por ejemplo bajo discos que sujetas con las manos.", "Eleva la cadera contra la banda hasta alinear rodillas, cadera y hombros.", "Baja la cadera con control.", "Repite el número de repeticiones indicado."]'::jsonb
