-- 126 band seated hip internal rotation
UPDATE exercises SET instructions_es = 'Siéntate en un cajón o banco con una banda en el tobillo anclada a un lado. Mantén el tronco erguido y la rodilla flexionada a 90°. Lleva el pie hacia el lado girando desde la cadera, sin mover la rodilla. Vuelve con control a la posición inicial. Completa las repeticiones y cambia de pierna. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en un cajón o banco con una banda en el tobillo anclada a un lado.", "Mantén el tronco erguido y la rodilla flexionada a 90°.", "Lleva el pie hacia el lado girando desde la cadera, sin mover la rodilla.", "Vuelve con control a la posición inicial.", "Completa las repeticiones y cambia de pierna.", "Repite el número de repeticiones indicado."]'::jsonb
