-- 131 band one arm overhead biceps curl
UPDATE exercises SET name_es = 'Curl de bíceps a una mano con banda y brazo a la altura del hombro', instructions_es = 'Ponte de pie de lado a una banda anclada a la altura del hombro. Sujeta la banda con una mano y extiende el brazo lateralmente a la altura del hombro, con la otra mano en la cadera. Flexiona el codo llevando la mano hacia la cabeza sin bajar el brazo. Extiende el codo con control. Completa las repeticiones y cambia de brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie de lado a una banda anclada a la altura del hombro.", "Sujeta la banda con una mano y extiende el brazo lateralmente a la altura del hombro, con la otra mano en la cadera.", "Flexiona el codo llevando la mano hacia la cabeza sin bajar el brazo.", "Extiende el codo con control.", "Completa las repeticiones y cambia de brazo.", "Repite el número de repeticiones indicado."]'::jsonb
