-- 132 band side triceps extension
UPDATE exercises SET instructions_es = 'Ponte de pie con una banda anclada al lado contrario del brazo que trabaja, a la altura de la cabeza. Sujeta la banda con una mano junto a la cabeza y el codo elevado a la altura del hombro. Extiende el brazo lateralmente hasta estirar el codo. Vuelve con control a la posición inicial. Completa las repeticiones y cambia de brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con una banda anclada al lado contrario del brazo que trabaja, a la altura de la cabeza.", "Sujeta la banda con una mano junto a la cabeza y el codo elevado a la altura del hombro.", "Extiende el brazo lateralmente hasta estirar el codo.", "Vuelve con control a la posición inicial.", "Completa las repeticiones y cambia de brazo.", "Repite el número de repeticiones indicado."]'::jsonb
