-- 323 cable bench press
UPDATE exercises SET instructions_es = 'Túmbate boca arriba en un banco plano entre dos poleas bajas, con los pies apoyados en el suelo. Sujeta un asa en cada mano a la altura del pecho, con los codos flexionados. Empuja las asas hacia arriba hasta extender los brazos sobre el pecho. Baja las asas con control hasta la altura del pecho. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate boca arriba en un banco plano entre dos poleas bajas, con los pies apoyados en el suelo.", "Sujeta un asa en cada mano a la altura del pecho, con los codos flexionados.", "Empuja las asas hacia arriba hasta extender los brazos sobre el pecho.", "Baja las asas con control hasta la altura del pecho.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 323 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '38755e42051703806803b3c5387b8c69';
-- 327 cable assisted inverse leg curl
UPDATE exercises SET instructions_es = 'Arrodíllate sobre la almohadilla de la máquina con los tobillos sujetos bajo los rodillos. Sujeta con ambas manos la barra unida a la polea alta, a la altura de los hombros, con el tronco erguido. Inclina el cuerpo hacia delante en bloque desde las rodillas, frenando la bajada con los isquiotibiales y la ayuda del cable. Desciende solo hasta donde puedas mantener el control. Vuelve a la posición erguida flexionando las rodillas. Repite el número de repeticiones indicado.', instruction_steps_es = '["Arrodíllate sobre la almohadilla de la máquina con los tobillos sujetos bajo los rodillos.", "Sujeta con ambas manos la barra unida a la polea alta, a la altura de los hombros, con el tronco erguido.", "Inclina el cuerpo hacia delante en bloque desde las rodillas, frenando la bajada con los isquiotibiales y la ayuda del cable.", "Desciende solo hasta donde puedas mantener el control.", "Vuelve a la posición erguida flexionando las rodillas.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 327 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '6c61e09658a20756d41536b0310e628c';
-- 328 cable alternate triceps extension
UPDATE exercises SET instructions_es = 'Ponte de pie junto a una polea baja y sujeta el asa con una mano. Lleva ese brazo por encima de la cabeza con el codo flexionado y la mano detrás de la cabeza. Extiende el codo hasta estirar el brazo por encima de la cabeza, sin mover la parte superior del brazo. Flexiona el codo con control para volver a la posición inicial. Completa las repeticiones y cambia de brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie junto a una polea baja y sujeta el asa con una mano.", "Lleva ese brazo por encima de la cabeza con el codo flexionado y la mano detrás de la cabeza.", "Extiende el codo hasta estirar el brazo por encima de la cabeza, sin mover la parte superior del brazo.", "Flexiona el codo con control para volver a la posición inicial.", "Completa las repeticiones y cambia de brazo.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 328 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '60baebf33af3dfa5a7b7c62a2de951f6';
-- 331 cable concentration extension (on knee)
UPDATE exercises SET instructions_es = 'Colócate con una rodilla apoyada en el suelo y el otro pie adelantado, bajo una polea alta. Sujeta el asa con la mano del lado de la pierna adelantada y apoya ese codo en la cara interna del muslo. Apoya la otra mano sobre la rodilla adelantada. Extiende el codo llevando el asa hacia el suelo, sin separar el brazo del muslo. Flexiona el codo con control para volver y cambia de lado al terminar. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate con una rodilla apoyada en el suelo y el otro pie adelantado, bajo una polea alta.", "Sujeta el asa con la mano del lado de la pierna adelantada y apoya ese codo en la cara interna del muslo.", "Apoya la otra mano sobre la rodilla adelantada.", "Extiende el codo llevando el asa hacia el suelo, sin separar el brazo del muslo.", "Flexiona el codo con control para volver y cambia de lado al terminar.", "Repite el número de repeticiones indicado."]'::jsonb
