-- 347 cable judo flip
UPDATE exercises SET instructions_es = 'Ponte de pie con una polea detrás de ti y ligeramente a un lado. Sujeta el asa con ambas manos junto a un hombro, con el cable pasando por encima de ese hombro. Flexiona la cadera y el tronco hacia delante tirando del cable hacia abajo, como en una proyección de judo. Baja hasta que el tronco quede casi horizontal y las manos cerca de las rodillas. Vuelve con control a la posición erguida. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con una polea detrás de ti y ligeramente a un lado.", "Sujeta el asa con ambas manos junto a un hombro, con el cable pasando por encima de ese hombro.", "Flexiona la cadera y el tronco hacia delante tirando del cable hacia abajo, como en una proyección de judo.", "Baja hasta que el tronco quede casi horizontal y las manos cerca de las rodillas.", "Vuelve con control a la posición erguida.", "Repite el número de repeticiones indicado."]'::jsonb
