UPDATE exercises SET name_es = 'Extensión de tríceps a una mano en polea alta', instructions_es = 'Ponte de pie frente a una polea alta y sujeta el asa con una mano. Pega el codo al costado, flexionado, con la mano a la altura del pecho. Extiende el codo hasta que el brazo quede recto junto al muslo. Vuelve despacio a la posición inicial sin separar el codo del cuerpo. Repite con el otro brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie frente a una polea alta y sujeta el asa con una mano.", "Pega el codo al costado, flexionado, con la mano a la altura del pecho.", "Extiende el codo hasta que el brazo quede recto junto al muslo.", "Vuelve despacio a la posición inicial sin separar el codo del cuerpo.", "Repite con el otro brazo.", "Repite el número de repeticiones indicado."]'::jsonb
