-- 452 cable standing pulldown (with rope)
UPDATE exercises SET instructions_es = 'Ponte de pie frente a una polea alta con una cuerda enganchada. Sujeta la cuerda con ambas manos y los brazos extendidos hacia la polea, con las manos a la altura de la cabeza o algo por encima. Flexiona los codos y tira de la cuerda hacia la cara. Extiende los brazos despacio hasta la posición inicial. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie frente a una polea alta con una cuerda enganchada.", "Sujeta la cuerda con ambas manos y los brazos extendidos hacia la polea, con las manos a la altura de la cabeza o algo por encima.", "Flexiona los codos y tira de la cuerda hacia la cara.", "Extiende los brazos despacio hasta la posición inicial.", "Repite el número de repeticiones indicado."]'::jsonb
