-- 456 chest and front of shoulder stretch
UPDATE exercises SET instructions_es = 'Ponte de pie sujetando un palo con ambas manos, con un agarre ancho, a la altura de la cadera. Eleva el palo hasta colocarlo detrás de la cabeza, a la altura de la nuca, flexionando los codos. Abre el pecho llevando los codos ligeramente hacia atrás, sin forzar. Vuelve despacio a la posición inicial. Mantén la duración indicada.', instruction_steps_es = '["Ponte de pie sujetando un palo con ambas manos, con un agarre ancho, a la altura de la cadera.", "Eleva el palo hasta colocarlo detrás de la cabeza, a la altura de la nuca, flexionando los codos.", "Abre el pecho llevando los codos ligeramente hacia atrás, sin forzar.", "Vuelve despacio a la posición inicial.", "Mantén la duración indicada."]'::jsonb
