-- 460 chest tap push-up (male)
UPDATE exercises SET name_es = 'Flexión pliométrica con toque de pecho', instructions_es = 'Colócate en plancha alta en el suelo con las manos algo más separadas que los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos. Empuja con fuerza para despegar las manos del suelo y toca el pecho con ambas manos en el aire. Vuelve a apoyar las manos y amortigua la caída flexionando los codos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate en plancha alta en el suelo con las manos algo más separadas que los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo flexionando los codos.", "Empuja con fuerza para despegar las manos del suelo y toca el pecho con ambas manos en el aire.", "Vuelve a apoyar las manos y amortigua la caída flexionando los codos.", "Repite el número de repeticiones indicado."]'::jsonb
