UPDATE exercises SET instructions_es = 'Ponte de pie de lado a una polea situada a la altura de la cintura y sujeta el asa con la mano más alejada de la polea. Pega el codo al costado, flexionado a 90 grados, con el antebrazo por delante del abdomen. Gira el antebrazo hacia fuera manteniendo el codo pegado al cuerpo. Vuelve despacio a la posición inicial. Repite con el otro brazo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie de lado a una polea situada a la altura de la cintura y sujeta el asa con la mano más alejada de la polea.", "Pega el codo al costado, flexionado a 90 grados, con el antebrazo por delante del abdomen.", "Gira el antebrazo hacia fuera manteniendo el codo pegado al cuerpo.", "Vuelve despacio a la posición inicial.", "Repite con el otro brazo.", "Repite el número de repeticiones indicado."]'::jsonb
