UPDATE exercises SET instructions_es = 'Túmbate boca arriba en un banco plano entre dos poleas altas. Sujeta un asa con cada mano, con los cables cruzados, y extiende los brazos hacia el techo. Con los codos casi extendidos, abre los brazos hacia los lados hasta la altura de los hombros. Vuelve despacio a la posición inicial. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate boca arriba en un banco plano entre dos poleas altas.", "Sujeta un asa con cada mano, con los cables cruzados, y extiende los brazos hacia el techo.", "Con los codos casi extendidos, abre los brazos hacia los lados hasta la altura de los hombros.", "Vuelve despacio a la posición inicial.", "Repite el número de repeticiones indicado."]'::jsonb
