-- 1004 lever deadlift
UPDATE exercises SET instructions_es = 'Colócate de pie en la máquina, entre las asas, con los pies separados a la anchura de las caderas. Flexiona la cadera y las rodillas y sujeta las asas a los lados con la espalda recta. Empuja el suelo con los pies y extiende la cadera y las rodillas hasta quedar de pie. Baja con control hasta la posición inicial manteniendo la espalda recta. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de pie en la máquina, entre las asas, con los pies separados a la anchura de las caderas.", "Flexiona la cadera y las rodillas y sujeta las asas a los lados con la espalda recta.", "Empuja el suelo con los pies y extiende la cadera y las rodillas hasta quedar de pie.", "Baja con control hasta la posición inicial manteniendo la espalda recta.", "Repite el número de repeticiones indicado."]'::jsonb
