UPDATE exercises SET instructions_es = 'Pasa una toalla resistente por un punto de anclaje firme a la altura de la cintura y comprueba que aguanta tu peso antes de empezar. Sujeta la toalla y colócate en cuclillas frente al anclaje con los pies cerca de él. Deja caer el cuerpo hacia atrás hasta extender los brazos, manteniendo los pies en su sitio. Tira de la toalla acercando el pecho al anclaje mientras juntas los omóplatos. Vuelve con control a la posición de brazos extendidos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Pasa una toalla resistente por un punto de anclaje firme a la altura de la cintura y comprueba que aguanta tu peso antes de empezar.", "Sujeta la toalla y colócate en cuclillas frente al anclaje con los pies cerca de él.", "Deja caer el cuerpo hacia atrás hasta extender los brazos, manteniendo los pies en su sitio.", "Tira de la toalla acercando el pecho al anclaje mientras juntas los omóplatos.", "Vuelve con control a la posición de brazos extendidos.", "Repite el número de repeticiones indicado."]'::jsonb
