-- 1074 lunge with jump
UPDATE exercises SET instructions_es = 'Colócate en posición de zancada con la pierna trasera flexionada y la rodilla cerca del suelo, sin apoyarla. Impúlsate con fuerza con la pierna delantera y lleva la rodilla trasera hacia el pecho, subiendo a la punta del pie de apoyo con un pequeño despegue. Recupera el apoyo de pie con control. Da un paso atrás para volver a la posición de zancada. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate en posición de zancada con la pierna trasera flexionada y la rodilla cerca del suelo, sin apoyarla.", "Impúlsate con fuerza con la pierna delantera y lleva la rodilla trasera hacia el pecho, subiendo a la punta del pie de apoyo con un pequeño despegue.", "Recupera el apoyo de pie con control.", "Da un paso atrás para volver a la posición de zancada.", "Repite el número de repeticiones indicado."]'::jsonb
