UPDATE exercises SET name_es = 'Flexión cerrada con pies sobre balón de estabilidad', instructions_es = 'Coloca las espinillas o los pies sobre un balón de estabilidad y las manos en el suelo, más juntas que la anchura de los hombros. Mantén el cuerpo en línea recta desde la cabeza hasta los pies. Flexiona los codos cerca del cuerpo y baja el pecho hacia el suelo. Empuja hasta extender los brazos sin perder la posición sobre el balón. Repite el número de repeticiones indicado.', instruction_steps_es = '["Coloca las espinillas o los pies sobre un balón de estabilidad y las manos en el suelo, más juntas que la anchura de los hombros.", "Mantén el cuerpo en línea recta desde la cabeza hasta los pies.", "Flexiona los codos cerca del cuerpo y baja el pecho hacia el suelo.", "Empuja hasta extender los brazos sin perder la posición sobre el balón.", "Repite el número de repeticiones indicado."]'::jsonb
