-- 1156 resistance band seated straight back row
UPDATE exercises SET instructions_es = 'Siéntate en un asiento con respaldo y apoya los pies en el reposapiés. Pasa la banda elástica alrededor de los pies y sujeta un extremo con cada mano con los brazos extendidos. Tira de la banda hacia la cintura juntando los omóplatos. Vuelve a extender los brazos con control. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en un asiento con respaldo y apoya los pies en el reposapiés.", "Pasa la banda elástica alrededor de los pies y sujeta un extremo con cada mano con los brazos extendidos.", "Tira de la banda hacia la cintura juntando los omóplatos.", "Vuelve a extender los brazos con control.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1156 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '7c8c0ab941fa8d95f4e600f12beebdf2';
-- 1157 resistance band hip thrusts on knees (female)
UPDATE exercises SET instructions_es = 'Ancla una banda elástica a un banco situado detrás de ti y pásala alrededor de la cadera. Colócate de rodillas sobre el suelo y siéntate hacia los talones con las manos junto al pecho. Contrae los glúteos y empuja la cadera hacia delante hasta quedar de rodillas con el tronco erguido. Vuelve con control a la posición sentada sobre los talones. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ancla una banda elástica a un banco situado detrás de ti y pásala alrededor de la cadera.", "Colócate de rodillas sobre el suelo y siéntate hacia los talones con las manos junto al pecho.", "Contrae los glúteos y empuja la cadera hacia delante hasta quedar de rodillas con el tronco erguido.", "Vuelve con control a la posición sentada sobre los talones.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1157 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '6209597dfdebc3ed5c337174d90428fa';
-- 1158 resistance band leg extension
UPDATE exercises SET instructions_es = 'Siéntate en un banco con una banda elástica alrededor de ambos tobillos. Apoya las manos en el banco y mantén el tronco erguido. Extiende una rodilla llevando el pie hacia delante contra la resistencia de la banda. Vuelve con control a la posición inicial. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en un banco con una banda elástica alrededor de ambos tobillos.", "Apoya las manos en el banco y mantén el tronco erguido.", "Extiende una rodilla llevando el pie hacia delante contra la resistencia de la banda.", "Vuelve con control a la posición inicial.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1158 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'e0a90a45cc37800bd5bf1dc6112caa15';
-- 1177 ski step
UPDATE exercises SET instructions_es = 'Ponte de pie con las manos en la cintura. Adelanta una pierna y lleva la otra hacia atrás. Intercambia la posición de las piernas con pasos cortos y rápidos. Mantén el tronco erguido durante todo el ejercicio. Mantén la duración indicada.', instruction_steps_es = '["Ponte de pie con las manos en la cintura.", "Adelanta una pierna y lleva la otra hacia atrás.", "Intercambia la posición de las piernas con pasos cortos y rápidos.", "Mantén el tronco erguido durante todo el ejercicio.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 1177 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'ce846ae6e2c0083818a533a8a6709c92';
-- 1181 seated side crunch (wall)
UPDATE exercises SET instructions_es = 'Apoya la espalda en una pared y desliza el cuerpo hasta quedar en posición de sentadilla con las manos en la cintura. Mantén esa posición con los pies firmes en el suelo. Inclina el tronco hacia un lado. Vuelve al centro y repite hacia el otro lado. Repite el número de repeticiones indicado.', instruction_steps_es = '["Apoya la espalda en una pared y desliza el cuerpo hasta quedar en posición de sentadilla con las manos en la cintura.", "Mantén esa posición con los pies firmes en el suelo.", "Inclina el tronco hacia un lado.", "Vuelve al centro y repite hacia el otro lado.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1181 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'cbdda9135693078054c70a41f568ab90';
-- 1188 seated lower back stretch
UPDATE exercises SET instructions_es = 'Siéntate erguido en una silla con respaldo y los pies apoyados en el suelo. Eleva ambos brazos estirados por encima de la cabeza. Estírate hacia arriba e inclina ligeramente el tronco hacia un lado y hacia el otro. Mantén los hombros relajados y la respiración tranquila. Mantén la duración indicada.', instruction_steps_es = '["Siéntate erguido en una silla con respaldo y los pies apoyados en el suelo.", "Eleva ambos brazos estirados por encima de la cabeza.", "Estírate hacia arriba e inclina ligeramente el tronco hacia un lado y hacia el otro.", "Mantén los hombros relajados y la respiración tranquila.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 1188 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '511dda3ebe406864b0e0bf41225a02f0';
