-- 1193 seated piriformis stretch
UPDATE exercises SET instructions_es = 'Siéntate en un banco o taburete bajo con los pies apoyados en el suelo. Cruza un tobillo sobre la rodilla contraria, formando un 4 con las piernas. Apoya los antebrazos sobre la pierna cruzada. Inclina el tronco hacia delante desde la cadera hasta notar el estiramiento en el glúteo. Vuelve despacio a la posición erguida y cambia de pierna cuando corresponda. Mantén la duración indicada.', instruction_steps_es = '["Siéntate en un banco o taburete bajo con los pies apoyados en el suelo.", "Cruza un tobillo sobre la rodilla contraria, formando un 4 con las piernas.", "Apoya los antebrazos sobre la pierna cruzada.", "Inclina el tronco hacia delante desde la cadera hasta notar el estiramiento en el glúteo.", "Vuelve despacio a la posición erguida y cambia de pierna cuando corresponda.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 1193 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '6815e2bf662cd460ec05c8538198ab18';
-- 1195 self assisted inverse leg curl
UPDATE exercises SET instructions_es = 'Arrodíllate sobre la almohadilla de la estación con los tobillos sujetos bajo los rodillos y los brazos cruzados sobre el pecho. Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos. Cuando no puedas frenar más, apoya las manos en el suelo para amortiguar la bajada. Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido. Repite el número de repeticiones indicado.', instruction_steps_es = '["Arrodíllate sobre la almohadilla de la estación con los tobillos sujetos bajo los rodillos y los brazos cruzados sobre el pecho.", "Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos.", "Cuando no puedas frenar más, apoya las manos en el suelo para amortiguar la bajada.", "Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1195 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '9eee49f67c2bbc5f8ea9de85cd225dc2';
-- 1196 self assisted inverse leg curl
UPDATE exercises SET instructions_es = 'Arrodíllate en el suelo con los talones enganchados bajo un banco estable y los brazos cruzados sobre el pecho. Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos. Al final de la bajada apoya las manos en el suelo y llega a la posición de flexión. Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido. Repite el número de repeticiones indicado.', instruction_steps_es = '["Arrodíllate en el suelo con los talones enganchados bajo un banco estable y los brazos cruzados sobre el pecho.", "Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos.", "Al final de la bajada apoya las manos en el suelo y llega a la posición de flexión.", "Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1196 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'b7dcccc50cdfa25cc1292f40185d9ed9';
-- 1197 self assisted inverse leg curl (on floor)
UPDATE exercises SET instructions_es = 'Arrodíllate sobre un step con los tobillos sujetos por una correa alrededor del step y los brazos cruzados sobre el pecho. Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos. Al final de la bajada apoya las manos en el suelo delante del step. Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido. Repite el número de repeticiones indicado.', instruction_steps_es = '["Arrodíllate sobre un step con los tobillos sujetos por una correa alrededor del step y los brazos cruzados sobre el pecho.", "Con el cuerpo recto de rodillas a cabeza, inclínate hacia delante despacio, frenando con la parte posterior de los muslos.", "Al final de la bajada apoya las manos en el suelo delante del step.", "Empuja con las manos lo justo para ayudarte y vuelve a la posición de rodillas con el tronco erguido.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1197 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '1266b6cdd4be44f4a5c9ef56b1516d0d';
-- 1199 side hip abduction
UPDATE exercises SET instructions_es = 'Túmbate de lado en el suelo con las piernas extendidas, apoyándote en la mano o el antebrazo de abajo. Mantén la cadera apoyada y el tronco estable. Eleva la pierna de arriba manteniéndola recta. Bájala despacio hasta juntarla con la otra pierna. Completa un lado y después cambia al otro. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate de lado en el suelo con las piernas extendidas, apoyándote en la mano o el antebrazo de abajo.", "Mantén la cadera apoyada y el tronco estable.", "Eleva la pierna de arriba manteniéndola recta.", "Bájala despacio hasta juntarla con la otra pierna.", "Completa un lado y después cambia al otro.", "Repite el número de repeticiones indicado."]'::jsonb
