-- 1200 side lying hip adduction (male)
UPDATE exercises SET instructions_es = 'Túmbate de lado en el suelo apoyándote en la mano de abajo, con la otra mano apoyada delante del cuerpo. Flexiona la pierna de arriba y apoya ese pie en el suelo por delante de la pierna de abajo. Mantén la pierna de abajo extendida y elévala del suelo. Bájala despacio sin llegar a descansar del todo. Completa un lado y después cambia al otro. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate de lado en el suelo apoyándote en la mano de abajo, con la otra mano apoyada delante del cuerpo.", "Flexiona la pierna de arriba y apoya ese pie en el suelo por delante de la pierna de abajo.", "Mantén la pierna de abajo extendida y elévala del suelo.", "Bájala despacio sin llegar a descansar del todo.", "Completa un lado y después cambia al otro.", "Repite el número de repeticiones indicado."]'::jsonb
