-- 1201 side plank hip adduction
UPDATE exercises SET instructions_es = 'Colócate de lado en plancha lateral sobre el antebrazo, con el codo bajo el hombro y el pie de arriba apoyado sobre un banco. Deja la pierna de abajo por debajo del banco. Eleva la cadera y lleva la pierna de abajo hacia el banco, manteniendo el cuerpo alineado. Baja la cadera y la pierna con control sin apoyarte del todo. Repite el gesto de forma continua y cambia de lado cuando corresponda. Mantén la duración indicada.', instruction_steps_es = '["Colócate de lado en plancha lateral sobre el antebrazo, con el codo bajo el hombro y el pie de arriba apoyado sobre un banco.", "Deja la pierna de abajo por debajo del banco.", "Eleva la cadera y lleva la pierna de abajo hacia el banco, manteniendo el cuerpo alineado.", "Baja la cadera y la pierna con control sin apoyarte del todo.", "Repite el gesto de forma continua y cambia de lado cuando corresponda.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 1201 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'd4231f7b9ed63ebd469cd24a367dc7df';
-- 1206 side push-up
UPDATE exercises SET instructions_es = 'Túmbate de lado en el suelo con las rodillas flexionadas. Apoya la mano de arriba en el suelo delante del pecho. Empuja con esa mano para elevar el tronco del suelo. Baja el tronco con control hasta la posición inicial. Completa un lado y después cambia al otro. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate de lado en el suelo con las rodillas flexionadas.", "Apoya la mano de arriba en el suelo delante del pecho.", "Empuja con esa mano para elevar el tronco del suelo.", "Baja el tronco con control hasta la posición inicial.", "Completa un lado y después cambia al otro.", "Repite el número de repeticiones indicado."]'::jsonb
