UPDATE exercises SET instructions_es = 'Colócate de pie junto a un soporte estable y sujétalo con una mano. Apoya la parte delantera del pie de apoyo sobre una mancuerna colocada en el suelo y flexiona la otra pierna hacia atrás. Eleva el talón lo más alto que puedas. Bájalo despacio por debajo del nivel de la punta. Completa una pierna y después cambia a la otra. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de pie junto a un soporte estable y sujétalo con una mano.", "Apoya la parte delantera del pie de apoyo sobre una mancuerna colocada en el suelo y flexiona la otra pierna hacia atrás.", "Eleva el talón lo más alto que puedas.", "Bájalo despacio por debajo del nivel de la punta.", "Completa una pierna y después cambia a la otra.", "Repite el número de repeticiones indicado."]'::jsonb
