-- 1213 smith one leg floor calf raise
UPDATE exercises SET instructions_es = 'Colócate de pie dentro de la máquina Smith con la barra apoyada sobre la parte alta de la espalda y las manos sujetándola. Flexiona una pierna hacia atrás para quedar apoyado sobre un solo pie. Eleva el talón del pie de apoyo lo más alto que puedas. Bájalo despacio hasta apoyarlo en el suelo. Completa una pierna y después cambia a la otra. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de pie dentro de la máquina Smith con la barra apoyada sobre la parte alta de la espalda y las manos sujetándola.", "Flexiona una pierna hacia atrás para quedar apoyado sobre un solo pie.", "Eleva el talón del pie de apoyo lo más alto que puedas.", "Bájalo despacio hasta apoyarlo en el suelo.", "Completa una pierna y después cambia a la otra.", "Repite el número de repeticiones indicado."]'::jsonb
