-- 1223 smith incline shoulder raises
UPDATE exercises SET instructions_es = 'Coloca un banco inclinado dentro de la máquina Smith y recuéstate con los pies apoyados en el suelo. Sujeta la barra con los brazos extendidos sobre el pecho. Sin doblar los codos, separa los hombros del respaldo empujando la barra unos centímetros hacia arriba. Baja despacio juntando las escápulas sin flexionar los codos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Coloca un banco inclinado dentro de la máquina Smith y recuéstate con los pies apoyados en el suelo.", "Sujeta la barra con los brazos extendidos sobre el pecho.", "Sin doblar los codos, separa los hombros del respaldo empujando la barra unos centímetros hacia arriba.", "Baja despacio juntando las escápulas sin flexionar los codos.", "Repite el número de repeticiones indicado."]'::jsonb
