-- 1225 smith hip raise
UPDATE exercises SET instructions_es = 'Túmbate boca arriba en el suelo dentro de la máquina Smith con los brazos a los lados. Eleva las piernas en vertical y apoya las plantas de los pies bajo la barra. Despega la cadera del suelo empujando la barra hacia arriba con los pies. Baja la cadera despacio hasta el suelo. Repite el número de repeticiones indicado.', instruction_steps_es = '["Túmbate boca arriba en el suelo dentro de la máquina Smith con los brazos a los lados.", "Eleva las piernas en vertical y apoya las plantas de los pies bajo la barra.", "Despega la cadera del suelo empujando la barra hacia arriba con los pies.", "Baja la cadera despacio hasta el suelo.", "Repite el número de repeticiones indicado."]'::jsonb
