-- 1254 standing calves
UPDATE exercises SET instructions_es = 'Colócate de pie frente a una pared y apoya las manos en ella a la altura de los hombros. Lleva los pies un poco hacia atrás, separados al ancho de las caderas. Inclina el cuerpo hacia la pared manteniendo los talones en el suelo. Vuelve despacio a la posición inicial. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de pie frente a una pared y apoya las manos en ella a la altura de los hombros.", "Lleva los pies un poco hacia atrás, separados al ancho de las caderas.", "Inclina el cuerpo hacia la pared manteniendo los talones en el suelo.", "Vuelve despacio a la posición inicial.", "Repite el número de repeticiones indicado."]'::jsonb
