-- 1255 standing calves calf stretch
UPDATE exercises SET instructions_es = 'Colócate de pie frente a un banco y apoya el talón de una pierna sobre él con la pierna recta. Mantén la otra pierna apoyada en el suelo. Inclina el tronco hacia delante y sujeta la punta del pie elevado. Tira suavemente de la punta hacia ti y vuelve a erguirte con control. Cambia de pierna cuando corresponda. Mantén la duración indicada.', instruction_steps_es = '["Colócate de pie frente a un banco y apoya el talón de una pierna sobre él con la pierna recta.", "Mantén la otra pierna apoyada en el suelo.", "Inclina el tronco hacia delante y sujeta la punta del pie elevado.", "Tira suavemente de la punta hacia ti y vuelve a erguirte con control.", "Cambia de pierna cuando corresponda.", "Mantén la duración indicada."]'::jsonb
