-- 1256 spine twist
UPDATE exercises SET instructions_es = 'Siéntate en el suelo con las piernas extendidas. Cruza los brazos delante del pecho a la altura de los hombros. Gira el tronco despacio hacia un lado. Vuelve al centro y gira hacia el otro lado. Alterna los lados. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en el suelo con las piernas extendidas.", "Cruza los brazos delante del pecho a la altura de los hombros.", "Gira el tronco despacio hacia un lado.", "Vuelve al centro y gira hacia el otro lado.", "Alterna los lados.", "Repite el número de repeticiones indicado."]'::jsonb
