-- 1268 spell caster
UPDATE exercises SET instructions_es = 'Ponte de pie con una mancuerna en cada mano. Gira el tronco y lleva las mancuernas junto a un lado de la cadera. Lleva ambas mancuernas en diagonal hacia delante hasta la altura de la cara, girando el tronco hacia el frente. Vuelve con control a la posición inicial. Repite el número de repeticiones indicado.', instruction_steps_es = '["Ponte de pie con una mancuerna en cada mano.", "Gira el tronco y lleva las mancuernas junto a un lado de la cadera.", "Lleva ambas mancuernas en diagonal hacia delante hasta la altura de la cara, girando el tronco hacia el frente.", "Vuelve con control a la posición inicial.", "Repite el número de repeticiones indicado."]'::jsonb
