-- 1272 snatch pull
UPDATE exercises SET instructions_es = 'Colócate de pie con la barra en el suelo frente a ti, baja en cuclillas y sujétala con las manos. Levanta la barra del suelo extendiendo cadera y rodillas con la espalda recta. Al pasar las rodillas, extiende la cadera de forma explosiva elevándote sobre las puntas y encogiendo los hombros. Baja la barra de nuevo al suelo con control. Repite el número de repeticiones indicado.', instruction_steps_es = '["Colócate de pie con la barra en el suelo frente a ti, baja en cuclillas y sujétala con las manos.", "Levanta la barra del suelo extendiendo cadera y rodillas con la espalda recta.", "Al pasar las rodillas, extiende la cadera de forma explosiva elevándote sobre las puntas y encogiendo los hombros.", "Baja la barra de nuevo al suelo con control.", "Repite el número de repeticiones indicado."]'::jsonb
