-- 1320 triceps dips floor
UPDATE exercises SET instructions_es = 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados. Coloca las manos en el suelo detrás de ti con los dedos hacia delante. Separa ligeramente la cadera del suelo. Flexiona los codos bajando el tronco y empuja hasta extenderlos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados.", "Coloca las manos en el suelo detrás de ti con los dedos hacia delante.", "Separa ligeramente la cadera del suelo.", "Flexiona los codos bajando el tronco y empuja hasta extenderlos.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1320 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '35c89cef3382d7de8a5a82d32ab5a728';
-- 1322 triceps stretch
UPDATE exercises SET instructions_es = 'Ponte de pie con la espalda recta. Lleva un brazo extendido a la altura del hombro por delante del pecho. Sujétalo con el otro brazo y acércalo suavemente al cuerpo. Suelta y repite con el otro brazo. Mantén la duración indicada.', instruction_steps_es = '["Ponte de pie con la espalda recta.", "Lleva un brazo extendido a la altura del hombro por delante del pecho.", "Sujétalo con el otro brazo y acércalo suavemente al cuerpo.", "Suelta y repite con el otro brazo.", "Mantén la duración indicada."]'::jsonb
 WHERE exercise_id = 1322 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '84de43c109cbaea145c1532c5b534a6c';
-- 1323 twin handle parallel grip lat pulldown
UPDATE exercises SET instructions_es = 'Siéntate en la máquina de polea alta con los muslos bajo los rodillos. Sujeta las dos asas por encima de la cabeza con los brazos extendidos. Tira de las asas hacia la parte alta del pecho llevando los codos hacia abajo. Sube las asas despacio hasta extender los brazos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate en la máquina de polea alta con los muslos bajo los rodillos.", "Sujeta las dos asas por encima de la cabeza con los brazos extendidos.", "Tira de las asas hacia la parte alta del pecho llevando los codos hacia abajo.", "Sube las asas despacio hasta extender los brazos.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1323 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '3576a14b032d4f2719eb7f3f4b218859';
-- 1337 wide grip rear pull-up
UPDATE exercises SET name_es = 'Dominada tras nuca con agarre ancho', instructions_es = 'Cuélgate de una barra fija con un agarre ancho. Tira del cuerpo hacia arriba llevando la cabeza por delante de la barra. Sube hasta que la barra quede a la altura de la nuca. Baja despacio hasta extender los brazos. Repite el número de repeticiones indicado.', instruction_steps_es = '["Cuélgate de una barra fija con un agarre ancho.", "Tira del cuerpo hacia arriba llevando la cabeza por delante de la barra.", "Sube hasta que la barra quede a la altura de la nuca.", "Baja despacio hasta extender los brazos.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1337 AND name_es = 'Dominada agarre ancho' AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = '9356b556c5f20d36488c3cb237896685';
-- 1338 weighted seated bicep curl (on stability ball)
UPDATE exercises SET instructions_es = 'Siéntate sobre un balón suizo con los pies apoyados en el suelo. Sujeta el peso con una mano y el brazo extendido junto al cuerpo. Flexiona el codo subiendo el peso hacia el hombro sin mover el brazo. Bájalo despacio. Completa un brazo y después cambia al otro. Repite el número de repeticiones indicado.', instruction_steps_es = '["Siéntate sobre un balón suizo con los pies apoyados en el suelo.", "Sujeta el peso con una mano y el brazo extendido junto al cuerpo.", "Flexiona el codo subiendo el peso hacia el hombro sin mover el brazo.", "Bájalo despacio.", "Completa un brazo y después cambia al otro.", "Repite el número de repeticiones indicado."]'::jsonb
 WHERE exercise_id = 1338 AND md5(regexp_replace(instructions_es, '[\t\r\n]+', ' ', 'g')) = 'c02b85e20d23dbebb94ffbf23d81a18d';
-- 1374 wind sprints
UPDATE exercises SET name_es = 'Elevación alterna de rodillas colgado en barra', instructions_es = 'Cuélgate de una barra fija con los brazos extendidos. Eleva una rodilla hacia el pecho. Bájala mientras elevas la otra. Alterna las piernas a ritmo constante. Repite el número de repeticiones indicado.', instruction_steps_es = '["Cuélgate de una barra fija con los brazos extendidos.", "Eleva una rodilla hacia el pecho.", "Bájala mientras elevas la otra.", "Alterna las piernas a ritmo constante.", "Repite el número de repeticiones indicado."]'::jsonb
